u3-2.html<pre><code>&lt;!DOCTYPE html&gt;
&lt;html lang="es"&gt;
&lt;head&gt;
  &lt;meta charset="UTF-8"&gt;
  &lt;meta name="viewport" content="width=device-width, initial-scale=1.0"&gt;
  &lt;title&gt;Reglamento de evaluación&lt;/title&gt;
&lt;/head&gt;
&lt;body&gt;
  &lt;!-- Primer elemento del body: el primer Tab lo alcanza antes que al menú --&gt;
