&lt;body&gt;
  &lt;main&gt;
    &lt;h1&gt;Casa del Olivar · Jaén&lt;/h1&gt;
    &lt;!-- Decorativa: alt vacío para que el lector la salte --&gt;
    &lt;img src="https://dummyimage.com/800x600/ccc/000.png&amp;text=patron.jpg" alt="" width="1200" height="60" loading="eager"&gt;
    &lt;figure&gt;
