      &lt;ul&gt;
        &lt;li&gt;&lt;a href="index.html"&gt;Inicio&lt;/a&gt;&lt;/li&gt;
        &lt;!-- aria-current="page": "estás aquí" para el lector de pantalla --&gt;
        &lt;li&gt;&lt;a href="novedades.html" aria-current="page"&gt;Novedades&lt;/a&gt;&lt;/li&gt;
